key.harness:
`timescale 1ns/1ps
// The grading testbench.
//
// The same eight rows, in a different order and at different times, and
// then three things the sample one does not do: change the SELECTED
// input while sel is held, change sel while both inputs are held, and
// walk the table twice to catch a design that answers correctly once
// and then latches.
module tb;
  logic a, b, sel, y;
  int wrong;

  mux2 dut (.a(a), .b(b), .sel(sel), .y(y));

  function automatic logic expected(logic xa, logic xb, logic xsel);
    return xsel ? xb : xa;
  endfunction

  task automatic drive(input logic xa, input logic xb, input logic xsel);
    a = xa; b = xb; sel = xsel;
    #5;
    if (y !== expected(xa, xb, xsel)) wrong++;
  endtask

  initial begin
    // All eight rows, descending, so an implementation that happens to
    // be right only on the way up is caught.
    wrong = 0;
    for (int i = 7; i >= 0; i--) drive(i[1], i[0], i[2]);
    $display("CHECK truth_table 0 %0d AT %0d", wrong, $time);

    // sel held at 0: y must track a, and must ignore b entirely.
    wrong = 0;
    sel = 1'b0; b = 1'b0;
    a = 1'b1; #5; if (y !== 1'b1) wrong++;
    b = 1'b1; #5; if (y !== 1'b1) wrong++;   // b changed; y must not
    a = 1'b0; #5; if (y !== 1'b0) wrong++;
    b = 1'b0; #5; if (y !== 1'b0) wrong++;
    $display("CHECK follows_a 0 %0d AT %0d", wrong, $time);

    // sel held at 1: the mirror image.
    wrong = 0;
    sel = 1'b1; a = 1'b0;
    b = 1'b1; #5; if (y !== 1'b1) wrong++;
    a = 1'b1; #5; if (y !== 1'b1) wrong++;   // a changed; y must not
    b = 1'b0; #5; if (y !== 1'b0) wrong++;
    a = 1'b0; #5; if (y !== 1'b0) wrong++;
    $display("CHECK follows_b 0 %0d AT %0d", wrong, $time);

    // sel moving while both inputs are held: y must switch with it.
    wrong = 0;
    a = 1'b0; b = 1'b1; #5;
    sel = 1'b0; #5; if (y !== 1'b0) wrong++;
    sel = 1'b1; #5; if (y !== 1'b1) wrong++;
    sel = 1'b0; #5; if (y !== 1'b0) wrong++;
    $display("CHECK sel_switches 0 %0d AT %0d", wrong, $time);

    // And the whole table twice over, to catch anything that holds.
    wrong = 0;
    for (int pass = 0; pass < 2; pass++) begin
      for (int i = 0; i < 8; i++) drive(i[1], i[0], i[2]);
    end
    $display("CHECK no_latch 0 %0d AT %0d", wrong, $time);

    $display("DONE 5");
    $finish;
  end
endmodule

reference.sv:
module mux2 (
  input  logic a,
  input  logic b,
  input  logic sel,
  output logic y
);

  assign y = sel ? b : a;

endmodule
